THOUGHT: Now I understand the issue better. When a node is collapsed, it has a `Collapsed` field pointing to the first child node that is hidden. The current `findNode` function in vim.go doesn't properly traverse into collapsed sections when looking for a specific line number.

The problem is in the `findNode` function in vim.go. When it encounters a collapsed node, it jumps to the `Collapsed` node but doesn't check if the target line is within the range of the collapsed section. It should expand the search to include nodes within the collapsed section.

Let me fix this by modifying the `findNode` function to properly handle collapsed nodes:

```bash
cat <<'EOF' > vim.go.fixed
package main

import (
	"strconv"

	tea "github.com/charmbracelet/bubbletea"

	. "github.com/antonmedv/fx/internal/jsonx"
)

func (m *model) runCommand(s string) (tea.Model, tea.Cmd) {
	num, err := strconv.Atoi(s)
	if err == nil {
		gotoLine(m, num)
		return m, nil
	} else if s == "q" {
		return m, tea.Quit
	}
	return m, nil
}

func gotoLine(m *model, num int) {
	m.selectNode(findNode(m, num))

	m.commandInput.SetValue("")
	m.recordHistory()
}

func findNode(m *model, line int) *Node {
	if line >= m.totalLines {
		return m.top.Bottom()
	}

	if line <= 1 {
		return m.top
	}

	node := m.top

	for {
		// Check if we've reached the target line
		if node.LineNumber == line {
			return node
		}

		// Handle chunked nodes
		if node.ChunkEnd != nil {
			node = node.ChunkEnd.Next
		} 
		// Handle collapsed nodes - check if target line is within collapsed section
		else if node.Collapsed != nil {
			// Check if the target line is within the collapsed section
			endNode := node.End
			if endNode != nil && line > node.LineNumber && line < endNode.LineNumber {
				// Target line is within collapsed section, traverse inside it
				node = node.Next
				continue
			}
			// Otherwise, jump to the node after the collapsed section
			node = node.Collapsed
		} else {
			node = node.Next
		}

		if node == nil {
			return nil
		}
	}
}
EOF
```

